import type { TaskRecord } from '@hachej/boring-ui-kit/task-board';

/** Exact adapter tokens only; terminal records must never revive stale viewer flags. Presentation is not authorization. */
export function compactTaskStatus(task: TaskRecord) {
  if (task.status === 'withdrawn' || task.status === 'abandoned' || task.status === 'closed' || (task.state === 'closed' && task.status !== 'shipped')) return 'closed';
  if (task.state === 'done' || task.status === 'shipped') return 'live';
  if (task.state === 'waiting' && task.waiting_on_you === true) return 'needs-you';
  if (task.status === 'blocked') return 'blocked';
  if (task.status === 'verifying') return 'verifying';
  return 'preparation';
}

/** Hosts author concise display titles; a legacy need is never shortened by cutting its sentence. */
export function compactTaskTitle(task: TaskRecord): string {
  return (task.display?.trim() || task.title.trim()).replace(/\s+/gu, ' ');
}

export const compactLabels = {
  en: { 'needs-you': 'Needs you', confirmation: 'To confirm', blocked: 'Blocked', verifying: 'Verification', live: 'Live', closed: 'Closed', withdrawn: 'Withdrawn', preparation: 'Preparing', finished: 'Finished', technical: 'Technical', empty: 'No requests', emptyDescription: 'No tasks match this view.' },
  fr: { 'needs-you': 'À vous', confirmation: 'À confirmer', blocked: 'Bloquée', verifying: 'Vérification', live: 'En ligne', closed: 'Fermée', withdrawn: 'Retirée', preparation: 'En préparation', finished: 'Terminées', technical: 'Technique', empty: 'Aucune demande', emptyDescription: 'Aucune demande dans cette vue.' },
} as const;

export const TASK_COLUMNS = ['needs-you', 'blocked', 'progress', 'live'] as const;
export type TaskColumn = typeof TASK_COLUMNS[number] | 'finished' | 'technical';
const RECENT_MS = 7 * 24 * 3_600_000;

/** Who acts next decides the column; shipped work stays visible for a week, then folds with everything finished. */
export function taskColumn(task: TaskRecord, now = Date.now()): TaskColumn {
  if (task.technical === true) return 'technical';
  const status = compactTaskStatus(task);
  if (status === 'closed') return 'finished';
  if (status === 'live') return now - (Date.parse(task.updated_at ?? '') || now) > RECENT_MS ? 'finished' : 'live';
  if (status === 'needs-you') return 'needs-you';
  return status === 'blocked' ? 'blocked' : 'progress';
}

export const columnLabels = {
  en: { 'needs-you': 'Needs you', blocked: 'Blocked', progress: 'In progress', live: 'Recently live', finished: 'Finished', technical: 'Technical' },
  fr: { 'needs-you': 'Attend votre avis', blocked: 'Bloquées', progress: 'En cours', live: 'En ligne récemment', finished: 'Terminées', technical: 'Technique' },
} as const;

/** What the waiting is about, when the host shared it: the viewer's open question first, then the projected one-line reason. */
export function taskWaitingText(task: TaskRecord): string | undefined {
  const open = task.waiting_on_you === true ? task.questions?.find(question => question.answer === undefined)?.text : undefined;
  return open ?? (task.state === 'waiting' ? task.waiting_on?.question?.trim() || undefined : undefined);
}

/** A card's second line: what is wanted or why it is stuck, else one plain status. */
export function taskCardLine(task: TaskRecord, locale: 'en' | 'fr' = 'en'): string {
  const status = compactTaskStatus(task), strings = compactLabels[locale];
  const label = status === 'closed' && (task.status === 'withdrawn' || task.status === 'abandoned') ? strings.withdrawn : strings[status];
  const waiting = status === 'needs-you' || status === 'blocked' ? taskWaitingText(task) : undefined;
  return !waiting ? label : status === 'needs-you' ? waiting : `${label}${locale === 'fr' ? ' : ' : ': '}${waiting}`;
}

/** The host's age when it formats one, else a short age from the last change. */
export function taskAge(task: TaskRecord, now = Date.now()): string | undefined {
  if (task.age) return task.age;
  const at = Date.parse(task.updated_at ?? '');
  if (!Number.isFinite(at)) return undefined;
  const minutes = Math.max(0, Math.round((now - at) / 60_000));
  return minutes < 60 ? `${minutes}m` : minutes < 1440 ? `${Math.round(minutes / 60)}h` : `${Math.round(minutes / 1440)}d`;
}

'use client';

import { useEffect, useRef, useState, useSyncExternalStore } from 'react';
import type { MouseEvent, ReactNode } from 'react';
import { selectTasks, taskFromUrl, taskReference, taskUrl } from '@hachej/boring-ui-kit/task-board';
import type { TaskFile, TaskFilter, TaskRecord } from '@hachej/boring-ui-kit/task-board';
import { ChevronLeftIcon } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from '@/components/ui/collapsible';
import { Empty, EmptyDescription, EmptyHeader, EmptyTitle } from '@/components/ui/empty';
import { Separator } from '@/components/ui/separator';
import { cn } from '../utils/utils';
import { TaskRequestCard, TaskStatusPill, taskMeta, taskTokens } from './task-request-card';
import type { TaskLocale, TaskViewerAction } from './task-request-card';
import { TaskDetail } from './task-detail';
import type { TaskDetailProps } from './task-detail';
import { columnLabels, compactLabels, compactTaskStatus, TASK_COLUMNS, taskColumn } from './compact-presentation';
import type { TaskColumn } from './compact-presentation';

export { TaskRequestCard, TaskRequestCard as TaskCard, TaskStatusPill, TaskStatusChip, TaskAttention, taskMeta, taskTokens } from './task-request-card';
export { TaskDetail } from './task-detail';
export type { TaskRequestCardProps, TaskRequestCardProps as TaskCardProps, TaskLocale, TaskViewerAction } from './task-request-card';
export type { TaskDetailProps } from './task-detail';
export type { TaskFile, TaskRecord, TaskFilter, TaskState } from '@hachej/boring-ui-kit/task-board';

const navigation = 'boring:task-navigation';
const subscribe = (changed: () => void) => {
  window.addEventListener('popstate', changed); window.addEventListener(navigation, changed);
  return () => { window.removeEventListener('popstate', changed); window.removeEventListener(navigation, changed); };
};
const readSelection = () => taskFromUrl(window.location.href);
const serverSelection = () => null;
const FOLDED = ['finished', 'technical'] as const;

export interface TaskFileViewApi {
  readonly fullscreen: boolean;
  readonly onFullscreenChange: (fullscreen: boolean) => void;
  readonly onClose: () => void;
  readonly onBack: () => void;
  /** The host's PM pointing service; absent unless onShowFile was supplied. */
  readonly onShowFile?: (() => void) | undefined;
}
export interface TaskBoardProps {
  readonly tasks: readonly TaskRecord[];
  /** Controlled Mine/All. Uncontrolled, the tasks bar starts on Mine when `currentUser` is known, otherwise All. */
  readonly filter?: TaskFilter;
  readonly onFilterChange?: ((filter: TaskFilter) => void) | undefined;
  readonly currentUser?: string;
  readonly limit?: number;
  readonly title?: string;
  /** @deprecated Ignored: columns follow who acts next and `locale`. */
  readonly labels?: unknown;
  /** The tasks bar (host content, app filter, Mine/All). Hosts that draw it in their own header pass false. */
  readonly bar?: boolean;
  /** Host content at the start of the tasks bar, e.g. the collapsed Studio header's app name and « Show the app ». */
  readonly barStart?: ReactNode;
  readonly locale?: TaskLocale;
  /** Explicit host context for compact French labels (« À vous » or « À confirmer »). */
  readonly viewerAction?: TaskViewerAction;
  /** Omit to use ?task= with native history. A router may instead supply controlled selection. */
  readonly selectedTask?: string | null;
  readonly onSelectedTaskChange?: ((id: string | null) => void) | undefined;
  /** Optional host navigation/present path, particularly for compact lists inside the PM panel. */
  readonly onOpen?: ((task: TaskRecord) => void) | undefined;
  /** Host content in the detail, after the question and the request. */
  readonly actions?: ((task: TaskRecord) => ReactNode) | undefined;
  readonly onAnswer?: TaskDetailProps['onAnswer'];
  readonly onOther?: TaskDetailProps['onOther'];
  readonly onDiscussQuestion?: TaskDetailProps['onDiscussQuestion'];
  readonly onAsk?: TaskDetailProps['onAsk'];
  /** Adapter paths only. The host reauthorizes them when opening the regular viewer. */
  readonly onOpenFile?: TaskDetailProps['onOpenFile'];
  readonly onShowFile?: TaskDetailProps['onOpenFile'];
  /** Supply the host's regular FileViewer; it opens 760px wide over the task detail. No second store or composer. */
  readonly renderFile?: ((task: TaskRecord, file: TaskFile, api: TaskFileViewApi) => ReactNode) | undefined;
  /** Host-owned overlay appearance (for example the host's overlay shadow token). */
  readonly overlayClassName?: string;
  readonly className?: string;
}

/**
 * The one task board: columns by who acts next (needs you, blocked, in progress, recently live), finished and technical folded. The
 * panel's own width decides the layout, so a narrow pane or phone gets the same sections stacked. The detail opens 400px wide over the
 * board, whole-pane when narrower; a file opens 760px wide over the detail.
 */
export function TaskBoard({ tasks, filter, onFilterChange, currentUser, limit, title = 'Tasks', bar = true, barStart, locale = 'en', viewerAction,
  selectedTask, onSelectedTaskChange, onOpen, actions, onAnswer, onOther, onDiscussQuestion, onAsk, onOpenFile, onShowFile, renderFile, overlayClassName, className }: TaskBoardProps) {
  const urlSelection = useSyncExternalStore(subscribe, readSelection, serverSelection);
  const [ownFilter, setOwnFilter] = useState<TaskFilter>(currentUser === undefined ? 'all' : 'mine');
  const [unfolded, setUnfolded] = useState<ReadonlySet<TaskColumn>>(() => new Set());
  const [app, setApp] = useState<string | null>(null);
  const shownFilter = filter ?? ownFilter;
  const selected = selectedTask === undefined ? onOpen ? null : urlSelection : selectedTask;
  const detail = selected === null ? undefined : tasks.find(task => task.id === selected || taskReference(task) === selected);
  const shown = selectTasks(tasks, { filter: shownFilter, ...(currentUser === undefined ? {} : { currentUser }), ...(limit === undefined ? {} : { limit }) });
  const [fileSelection, setFileSelection] = useState<{ readonly taskId: string; readonly path: string } | null>(null);
  const filePath = fileSelection?.path;
  const file = detail?.id === fileSelection?.taskId ? detail?.files?.find(candidate => candidate.path === filePath) : undefined;
  const fileOpen = !!file && !!renderFile;
  const [fileFullscreen, setFileFullscreen] = useState(false);
  const closeFile = () => { setFileSelection(null); setFileFullscreen(false); };
  const openFile = (task: TaskRecord, file: TaskFile) => { setFileSelection({ taskId: task.id, path: file.path }); onOpenFile?.(task, file); };
  const root = useRef<HTMLElement>(null);
  const back = useRef<HTMLButtonElement>(null);
  const previous = useRef<{ readonly id: string; readonly column: TaskColumn | undefined } | null>(null);
  const detailColumn = detail && taskColumn(detail);
  const pendingFocus = useRef<string | null>(null);
  const cardLink = (id: string) => [...root.current?.querySelectorAll<HTMLAnchorElement>('[data-task-open]') ?? []].find(candidate => candidate.dataset['taskOpen'] === id);
  const unfold = (column: TaskColumn, open: boolean) => setUnfolded(current => { const next = new Set(current); if (open) next.add(column); else next.delete(column); return next; });
  useEffect(() => {
    if (selected !== null) back.current?.focus();
    else if (previous.current !== null) {
      const { id, column } = previous.current, link = cardLink(id);
      if (link) link.focus();
      else if (column) { pendingFocus.current = id; unfold(column, true); }
    }
    previous.current = selected === null ? null : { id: detail?.id ?? selected, column: detailColumn };
  }, [selected, detail?.id, detailColumn]);
  useEffect(() => { if (pendingFocus.current !== null) { cardLink(pendingFocus.current)?.focus(); pendingFocus.current = null; } }, [unfolded]);
  const select = (id: string | null) => {
    closeFile();
    if (selectedTask === undefined) {
      window.history.pushState(null, '', taskUrl(window.location.href, id));
      window.dispatchEvent(new Event(navigation));
    }
    onSelectedTaskChange?.(id);
  };
  const open = (task: TaskRecord) => { if (onOpen) onOpen(task); else select(task.id); };
  const href = (task: TaskRecord) => typeof window === 'undefined' ? `?task=${encodeURIComponent(task.id)}` : taskUrl(window.location.href, task.id);
  const card = (task: TaskRecord) => <TaskRequestCard key={task.id} task={task} selected={task.id === detail?.id} href={href(task)} onOpen={open}
    locale={locale} viewerAction={viewerAction} />;
  const apps = [...new Set(shown.flatMap(task => task.app ? [task.app] : []))].sort();
  const listed = app === null ? shown : shown.filter(task => task.app === app);
  const words = columnLabels[locale];
  const of = (column: TaskColumn) => listed.filter(task => taskColumn(task) === column).sort((a, b) => (Date.parse(b.updated_at ?? '') || 0) - (Date.parse(a.updated_at ?? '') || 0));
  const appChip = (value: string | null, text: string) => <Badge key={text} data-task-app-filter={text} variant={app === value ? 'default' : 'secondary'} render={<a href="#" aria-current={app === value ? 'true' : undefined} onClick={(event: MouseEvent) => { event.preventDefault(); setApp(value); }} />}>{text}</Badge>;
  const chooseFilter = (next: TaskFilter) => (event: MouseEvent) => { event.preventDefault(); if (filter === undefined) setOwnFilter(next); onFilterChange?.(next); };
  return <section ref={root} data-boring="task-board" aria-label={title} className={cn('flex min-h-0 min-w-0 flex-col', className)} onKeyDown={event => {
    if (event.key === 'Escape' && selected !== null && !event.defaultPrevented) { event.preventDefault(); if (fileOpen) closeFile(); else select(null); }
  }}>
    {bar && (barStart || apps.length > 1 || currentUser !== undefined) && <nav data-task-bar aria-label="Task lists" className="flex h-13 shrink-0 items-center gap-2.5 px-3.5 text-[13px] text-muted-foreground">
      {barStart}
      {apps.length > 1 && <span className={cn('flex min-w-0 items-center gap-1.5 overflow-x-auto [scrollbar-width:none] *:shrink-0', taskTokens.pill)} data-task-apps="">{appChip(null, locale === 'fr' ? 'Toutes' : 'All apps')}{apps.map(name => appChip(name, name))}</span>}
      {currentUser !== undefined && <span className={cn('ml-auto flex items-center gap-2.5', taskTokens.pill)} data-task-filter={shownFilter}>
        {(['mine', 'all'] as const).map(value => <Badge key={value} variant={shownFilter === value ? 'default' : 'secondary'} render={<a href="#" aria-current={shownFilter === value ? 'true' : undefined} onClick={chooseFilter(value)} />}>{value === 'mine' ? 'Mine' : 'All'}</Badge>)}
      </span>}
    </nav>}
    <div data-task-stage className="relative min-h-0 flex-1 overflow-hidden">
      <div data-task-list className="@container/task-rails h-full min-w-0 overflow-auto">
        {!!listed.length && <div className="grid min-w-0 content-start gap-2.5 p-3.5 @3xl/task-rails:grid-cols-4">
          {TASK_COLUMNS.map(column => {
            const rows = of(column);
            // Stacked, an empty section is noise; side by side, a column keeps its place so the board does not shift.
            return <section key={column} data-task-column={column} aria-label={words[column]} className={cn('min-w-0 flex-col gap-[7px] self-start bg-muted p-2', rows.length ? 'flex' : 'hidden @3xl/task-rails:flex', taskTokens.column)}>
              <h3 className="flex min-h-6 items-center gap-1.5 px-0.5 pb-0.5 text-xs font-semibold text-muted-foreground">{words[column]}<span className="font-normal">{rows.length}</span></h3>
              <div role="list" className="flex flex-col gap-[7px]">{rows.map(card)}</div>
            </section>;
          })}
        </div>}
        {!listed.length && <Empty><EmptyHeader><EmptyTitle>{compactLabels[locale].empty}</EmptyTitle><EmptyDescription>{compactLabels[locale].emptyDescription}</EmptyDescription></EmptyHeader></Empty>}
        {FOLDED.map(column => {
          const rows = of(column);
          return rows.length > 0 && <div key={column} className="px-3.5 pb-2"><Collapsible data-task-group={column} open={unfolded.has(column)} onOpenChange={open => unfold(column, open)}>
            <CollapsibleTrigger render={<Button variant="ghost" size="sm" />}>{words[column]} · {rows.length}</CollapsibleTrigger>
            <CollapsibleContent><div role="list" aria-label={words[column]} className="grid gap-[7px] pt-1.5 @3xl/task-rails:grid-cols-4">{rows.map(card)}</div></CollapsibleContent>
          </Collapsible></div>;
        })}
      </div>
      {selected !== null && <aside aria-label="Task detail" data-task-side className={cn('absolute inset-y-0 right-0 flex w-[400px] max-w-full flex-col bg-popover text-popover-foreground', overlayClassName)} aria-live="polite">
        <Separator orientation="vertical" className="absolute inset-y-0 left-0" />
        <div className="flex h-10 shrink-0 items-center gap-2 pr-1.5 pl-3.5">
          <Button ref={back} variant="ghost" size="icon" data-task-back="" aria-label="Back to the tasks" title="Back to the tasks" onClick={() => select(null)}><ChevronLeftIcon aria-hidden="true" /></Button>
          {detail && <><span className="text-[11px] text-muted-foreground">{[detail.app, taskMeta(detail)].filter(Boolean).join(' · ')}</span><TaskStatusPill task={detail} locale={locale} viewerAction={viewerAction} /></>}
        </div>
        <Separator />
        <div className="min-h-0 flex-1 overflow-auto p-3.5">
          {detail ? <TaskDetail key={detail.id} task={detail} locale={locale} actions={actions?.(detail)} onAnswer={onAnswer} onOther={onOther} onDiscussQuestion={onDiscussQuestion} onAsk={onAsk} onOpenFile={renderFile || onOpenFile ? openFile : undefined} />
            : <Empty><EmptyHeader><EmptyTitle>Task unavailable</EmptyTitle><EmptyDescription>The host has not supplied this task.</EmptyDescription></EmptyHeader></Empty>}
        </div>
      </aside>}
      {fileOpen && detail && file && <section aria-label="Task file viewer" data-task-file-pane={detail.id} className={cn('flex min-w-0 flex-col bg-background', fileFullscreen ? 'fixed inset-0 z-50' : 'absolute inset-y-0 right-0 w-[760px] max-w-full', overlayClassName)}>
        {renderFile!(detail, file, { fullscreen: fileFullscreen, onFullscreenChange: setFileFullscreen, onClose: closeFile, onBack: closeFile, onShowFile: onShowFile ? () => onShowFile(detail, file) : undefined })}
      </section>}
    </div>
  </section>;
}

'use client';

import type { MouseEvent, ReactNode } from 'react';
import type { TaskRecord, TaskState } from '@hachej/boring-ui-kit/task-board';
import { deriveTaskStatus, taskReference, taskStatusLabel } from '@hachej/boring-ui-kit/task-board';
import { Badge } from '@/components/ui/badge';
import { Item } from '@/components/ui/item';
import { cn } from '../utils/utils';
import { compactLabels, compactTaskStatus, compactTaskTitle, taskAge, taskCardLine } from './compact-presentation';

export type TaskLocale = 'en' | 'fr';
export type TaskViewerAction = 'question' | 'confirmation';
export const taskStateLabels: Readonly<Record<TaskState, string>> = { waiting: 'Waiting', working: 'Working', open: 'Open', done: 'Done', closed: 'Closed' };
/**
 * Task-board tokens, set by the host theme. Each falls back to the stock shadcn value, so a host without them looks unchanged.
 * `--task-pill-height` / `--task-pill-font-size` (pills), `--task-control-height` (question controls), `--task-column-radius`,
 * `--task-card-padding-y` / `--task-card-padding-x` (board cards).
 */
export const taskTokens = {
  pill: '*:h-[var(--task-pill-height,1.25rem)] *:text-[length:var(--task-pill-font-size,0.75rem)]',
  control: '*:h-[var(--task-control-height,2rem)]',
  card: '[&_[data-slot=item]]:px-[var(--task-card-padding-x,0.75rem)] [&_[data-slot=item]]:py-[var(--task-card-padding-y,0.625rem)]',
  column: 'rounded-[var(--task-column-radius,var(--radius-xl))]',
} as const;

/** `id · age`, e.g. « D-201 · 12m ». */
export const taskMeta = (task: TaskRecord) => [taskReference(task), task.age].filter(Boolean).join(' · ');

/**
 * One pill per task: viewer, explicit builder, then high risk (`deriveTaskStatus`); none renders nothing. Colours are theme roles:
 * primary (waiting on you), secondary (builder, sent), destructive (risk). The French app's « À confirmer / À vous » pill uses the host's
 * warning-soft tokens when it defines them. `sent` lets standalone callers opt into « Envoyée »; compact rows use their separate product status.
 */
export function TaskStatusPill({ task, locale = 'en', viewerAction = 'question', sent = false }: { readonly task: Pick<TaskRecord, 'waiting_on_you' | 'waiting_on' | 'risk'> & Partial<Pick<TaskRecord, 'state' | 'confirmed_at'>>; readonly locale?: TaskLocale | undefined; readonly viewerAction?: TaskViewerAction | undefined; readonly sent?: boolean | undefined }) {
  const status = deriveTaskStatus(task, { sent });
  const label = taskStatusLabel(status, locale, viewerAction);
  if (!label) return null;
  const warning = status === 'waiting-on-viewer' && locale === 'fr';
  const badge = <Badge data-task-status={status} variant={status === 'waiting-on-viewer' && !warning ? 'default' : status === 'high-risk' ? 'destructive' : 'secondary'}>{label}</Badge>;
  return <span className={cn('contents', taskTokens.pill, warning && '[--secondary:var(--warning-soft,var(--secondary))] [--secondary-foreground:var(--warning-soft-foreground,var(--secondary-foreground))]')}>{badge}</span>;
}
/** @deprecated The pill now follows `deriveTaskStatus`; `labels` is ignored. */
export const TaskStatusChip = TaskStatusPill as (props: { readonly task: Pick<TaskRecord, 'waiting_on_you' | 'waiting_on' | 'risk'>; readonly labels?: unknown; readonly locale?: TaskLocale; readonly viewerAction?: TaskViewerAction }) => ReactNode;

/** A card waiting on the viewer carries a 2px foreground edge: the outline border plus a 1px ring, both in the primary role. */
export function TaskAttention({ active, children }: { readonly active: boolean; readonly children: ReactNode }) {
  return active ? <div data-task-attention="" className="rounded-[var(--radius-lg)] ring-1 ring-primary [--border:var(--primary)]">{children}</div> : <>{children}</>;
}

export interface TaskRequestCardProps {
  readonly task: TaskRecord;
  /** `card`: the board card (D2). `compact`: the app's request card (C7). */
  readonly variant?: 'card' | 'compact';
  readonly selected?: boolean;
  readonly href?: string;
  readonly onOpen?: ((task: TaskRecord) => void) | undefined;
  /** Host-authorized actions of the compact card, e.g. « Modifier » and « Confirmer »; rendered as two equal columns. */
  readonly actions?: ReactNode;
  readonly locale?: TaskLocale | undefined;
  /** Explicit host context for the French viewer label: « À vous » (question) or « À confirmer » (confirmation). */
  readonly viewerAction?: TaskViewerAction | undefined;
  /** Compact only: replaces the derived status pill, e.g. a finished request's muted « En ligne » in « Mes demandes ». */
  readonly pill?: ReactNode;
  /** @deprecated Ignored; kept for source compatibility. */
  readonly labels?: unknown;
}

/** One record, two renderings: the board card (D2) and the compact request card (C7). Actions remain host-authorized. */
export function TaskRequestCard({ task, variant = 'card', selected, href, onOpen, actions, locale = 'en', viewerAction, pill: shownPill }: TaskRequestCardProps) {
  const activate = (event: MouseEvent<HTMLAnchorElement>) => {
    if (!onOpen || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey || event.button !== 0) return;
    event.preventDefault(); onOpen(task);
  };
  const anchor = { href, onClick: activate, 'data-task-open': task.id, 'aria-current': selected ? 'true' as const : undefined };
  const link = href ? <a {...anchor} /> : undefined;
  if (variant === 'compact') {
    const status = compactTaskStatus(task);
    const strings = compactLabels[locale];
    const label = status === 'needs-you' && viewerAction === 'confirmation' ? strings.confirmation
      : status === 'closed' && (task.status === 'withdrawn' || task.status === 'abandoned') ? strings.withdrawn : strings[status];
    const pill = shownPill ?? <Badge data-task-status={status} variant={status === 'needs-you' ? 'default' : status === 'blocked' ? 'destructive' : 'secondary'}>{label}</Badge>;
    const shortTitle = compactTaskTitle(task);
    const title = link && actions ? <a {...anchor} className="underline-offset-4 hover:underline">{shortTitle}</a> : shortTitle;
    return <div role="listitem"><Item variant="outline" className="flex-col items-stretch gap-2" data-task-card={task.id} data-variant="compact" {...(link && !actions ? { render: link } : {})}>
      <div className="flex min-w-0 items-start justify-between gap-2">
        <span data-task-title="" className="min-w-0 text-sm font-semibold break-words">{title}</span>
        <span className="shrink-0">{pill}</span>
      </div>
      {actions && <div data-task-actions="" className="mt-1 grid grid-cols-2 gap-2 *:min-h-11 *:w-full">{actions}</div>}
    </Item></div>;
  }
  const needsYou = compactTaskStatus(task) === 'needs-you';
  const facts = [task.app, taskAge(task)].filter(Boolean).join(' · ');
  return <div role="listitem" className={cn('rounded-[var(--radius-lg)] bg-card', taskTokens.card)}>
    <Item variant="outline" className="flex-col items-stretch gap-1" data-task-card={task.id} data-selected={selected || undefined} {...(link ? { render: link } : {})}>
      <span data-task-title="" className="line-clamp-2 min-w-0 text-sm font-medium break-words text-foreground">{compactTaskTitle(task)}</span>
      <span data-task-line="" className={cn('line-clamp-2 min-w-0 text-[13px] break-words', needsYou ? 'text-foreground' : 'text-muted-foreground')}>{taskCardLine(task, locale)}</span>
      {facts && <span data-task-facts="" className="text-[11px] text-muted-foreground">{facts}</span>}
    </Item>
  </div>;
}

'use client';

import { useState } from 'react';
import type { ReactNode } from 'react';
import { AppWindowIcon, ChevronRightIcon, FileIcon, ImageIcon } from 'lucide-react';
import type { TaskFile, TaskQuestion, TaskRecord } from '@hachej/boring-ui-kit/task-board';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Item } from '@/components/ui/item';
import { TaskAttention, taskTokens } from './task-request-card';
import type { TaskLocale } from './task-request-card';
import { compactLabels, compactTaskStatus, compactTaskTitle, taskWaitingText } from './compact-presentation';

export interface TaskDetailProps {
  readonly task: TaskRecord;
  readonly locale?: TaskLocale | undefined;
  /** Host content after the question and the request (for example a mount report or host-authorized request actions). */
  readonly actions?: ReactNode;
  /** The host reauthorizes and resolves the original question. Rendering never supplies approval. */
  readonly onAnswer?: ((task: TaskRecord, question: TaskQuestion, value: string) => void) | undefined;
  /** « Other… » opens an inline field; Send passes the typed text. No synthetic option value or approval is generated. */
  readonly onOther?: ((task: TaskRecord, question: TaskQuestion, text: string) => void) | undefined;
  /** « Discuss in chat »: the host stages `@ D-201 · <title>` and the question in its one composer, without sending. */
  readonly onDiscussQuestion?: ((task: TaskRecord, question: TaskQuestion) => void) | undefined;
  readonly onOpenFile?: ((task: TaskRecord, file: TaskFile) => void) | undefined;
  /** « Ask in the conversation »: the host focuses its composer with the task mention. */
  readonly onAsk?: ((task: TaskRecord) => void) | undefined;
  /** @deprecated Ignored; kept for source compatibility. */
  readonly labels?: unknown;
}
const detailWords = {
  en: { question: 'QUESTION FOR YOU', waiting: 'WAITING ON YOU', elsewhere: 'Reply in the conversation.', request: 'THE REQUEST', yourAnswer: 'Your answer', send: 'Send', other: 'Other…', discuss: 'Discuss in chat', ask: 'Ask in the conversation' },
  fr: { question: 'QUESTION POUR VOUS', waiting: 'ATTEND VOTRE AVIS', elsewhere: 'Répondez dans la conversation.', request: 'LA DEMANDE', yourAnswer: 'Votre réponse', send: 'Envoyer', other: 'Autre…', discuss: 'En parler dans la conversation', ask: 'Demander dans la conversation' },
} as const;
const preview = (value: string) => value.length > 160 ? `${value.slice(0, 160)}…` : value;
const sectionLabel = 'text-[11px] font-semibold tracking-[0.06em] text-muted-foreground';
const kinds = { markdown: ['Markdown', FileIcon], mockup: ['Mockup', AppWindowIcon], capture: ['Capture', ImageIcon] } as const;
const fileKind = (file: TaskFile) => file.kind ?? (/\.(?:md|markdown)$/i.test(file.path) ? 'markdown' : /\.html?$/i.test(file.path) ? 'mockup' : /\.(?:png|jpe?g|gif|webp|svg)$/i.test(file.path) ? 'capture' : undefined);
/** ISO times show as local HH:MM; host-formatted strings show as given. */
const clock = (value: string) => /^\d{4}-\d\d-\d\dT/.test(value) && Number.isFinite(Date.parse(value)) ? new Date(value).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }) : value;

function AnsweredQuestion({ question }: { readonly question: TaskQuestion }) {
  const [expanded, setExpanded] = useState(false);
  return <li data-task-answered={question.id} className="min-w-0">
    <Button variant="ghost" className="grid h-auto w-full min-w-0 grid-cols-[minmax(0,1fr)_auto] justify-normal gap-x-2 gap-y-0.5 text-start whitespace-normal" aria-expanded={expanded} onClick={() => setExpanded(value => !value)}>
      <span className="truncate text-[13px] font-normal">{preview(question.text)}</span>
      <ChevronRightIcon aria-hidden="true" className="text-muted-foreground" />
      <span data-task-answer={question.id} className="col-span-full truncate text-[13px] font-normal text-muted-foreground">{question.answeredBy ? `${preview(question.answeredBy)}: ` : ''}{preview(question.answer ?? '')}</span>
    </Button>
    {expanded && <div data-task-answer-full className="flex flex-col gap-1 px-2 pb-2 text-[13px] break-words whitespace-pre-wrap"><p>{question.text}</p><p className="text-muted-foreground">{question.answeredBy && <>{question.answeredBy}: </>}{question.answer}</p></div>}
  </li>;
}

function OpenQuestion({ task, question, locale = 'en', onAnswer, onOther, onDiscussQuestion }: Pick<TaskDetailProps, 'task' | 'locale' | 'onAnswer' | 'onOther' | 'onDiscussQuestion'> & { readonly question: TaskQuestion }) {
  // Without options typing is the only way to answer, so the field is simply there.
  const typed = !question.options?.length;
  const [other, setOther] = useState<string | null>(typed && onOther ? '' : null);
  const words = detailWords[locale];
  const send = () => { const text = other?.trim(); if (text) { onOther?.(task, question, text); setOther(typed ? '' : null); } };
  const asked = [question.askedBy, question.askedAt && clock(question.askedAt)].filter(Boolean).join(' · ');
  return <TaskAttention active>
    <Item variant="outline" className="flex-col items-stretch gap-2" data-task-question={question.id}>
      <div className="flex items-baseline justify-between gap-2"><span className={sectionLabel}>{words.question}</span>{asked && <span className="text-[11px] text-muted-foreground">{asked}</span>}</div>
      <p className="text-sm">{question.text}</p>
      <div className={`flex items-center gap-2 ${taskTokens.control}`}>
        {question.options?.map((option, index) => {
          const value = typeof option === 'string' ? option : option.value;
          const label = typeof option === 'string' ? option : option.label;
          return <Button key={index} variant={index === 0 ? 'default' : 'outline'} disabled={!onAnswer} onClick={() => onAnswer?.(task, question, value)}>{label}</Button>;
        })}
        {onOther && !typed && <Button variant="outline" data-task-other={question.id} aria-expanded={other !== null} onClick={() => setOther(value => value === null ? '' : null)}>{words.other}</Button>}
        {onDiscussQuestion && <Button variant="link" className="h-auto min-w-0 shrink text-center leading-tight whitespace-normal underline" data-task-discuss={question.id} onClick={() => onDiscussQuestion(task, question)}>{words.discuss}</Button>}
      </div>
      {other !== null && <form className={`flex gap-2 ${taskTokens.control}`} data-task-other-form={question.id} onSubmit={event => { event.preventDefault(); send(); }}>
        <Input autoFocus={!typed} aria-label={words.yourAnswer} maxLength={4096} value={other} onChange={event => setOther(event.target.value)} onKeyDown={event => { if (event.key === 'Escape' && !typed) { event.preventDefault(); setOther(null); } }} />
        <Button type="submit" disabled={!other.trim()}>{words.send}</Button>
      </form>}
    </Item>
  </TaskAttention>;
}

/** Task detail (spec 3 §4), in order: title, the open question for the viewer, Answered, Files, « Ask in the conversation ». */
export function TaskDetail({ task, locale = 'en', actions, onAnswer, onOther, onDiscussQuestion, onOpenFile, onAsk }: TaskDetailProps) {
  const [showAll, setShowAll] = useState(false);
  const open = task.waiting_on_you === true ? task.questions?.find(question => question.answer === undefined) : undefined;
  const words = detailWords[locale];
  const status = compactTaskStatus(task);
  // Nothing openable may say it needs someone without saying what: the projected reason shows when there is no full question.
  const reason = !open && (status === 'needs-you' || status === 'blocked') ? taskWaitingText(task) : undefined;
  const answered = task.questions?.filter(question => question.answer !== undefined).toReversed().sort((a, b) => (Date.parse(b.answeredAt ?? '') || 0) - (Date.parse(a.answeredAt ?? '') || 0)) ?? [];
  const meta = [task.screen && `Screen: ${task.screen}`, task.requester && `asked by ${task.requester}`, task.refiner && `refined by ${task.refiner}`].filter(Boolean).join(' · ');
  const folder = task.folder?.replace(/\/?$/, '/');
  return <div className="flex min-w-0 flex-col gap-2.5" data-task-detail={task.id}>
    <div className="rounded-[var(--radius-lg)] bg-card"><Item variant="outline" className="flex-col items-stretch gap-1" data-task-title-card="">
      <h2 className="text-base font-semibold break-words">{compactTaskTitle(task)}</h2>
      {compactTaskTitle(task) !== task.title.trim() && <p className="text-[13px] break-words text-muted-foreground">{task.title}</p>}
      {meta && <p className="text-xs text-muted-foreground">{meta}</p>}
    </Item></div>
    {open && <div className="rounded-[var(--radius-lg)] bg-card"><OpenQuestion key={open.id} task={task} question={open} locale={locale} onAnswer={onAnswer} onOther={onOther} onDiscussQuestion={onDiscussQuestion} /></div>}
    {(reason || status === 'needs-you' && !open) && <div className="rounded-[var(--radius-lg)] bg-card" data-task-reason=""><TaskAttention active={status === 'needs-you'}><Item variant="outline" className="flex-col items-stretch gap-1">
      <span className={sectionLabel}>{status === 'needs-you' ? words.waiting : compactLabels[locale].blocked}</span>
      {reason && <p className="text-sm break-words">{reason}</p>}
      {status === 'needs-you' && <p className="text-[13px] text-muted-foreground">{words.elsewhere}</p>}
    </Item></TaskAttention></div>}
    {task.spec && task.spec.trim() !== task.title.trim() && <section aria-label={words.request} className="rounded-[var(--radius-lg)] bg-card" data-task-spec=""><Item variant="outline" className="flex-col items-stretch gap-1">
      <h3 className={sectionLabel}>{words.request}</h3>
      <p className="text-sm break-words whitespace-pre-wrap">{task.spec}</p>
    </Item></section>}
    {actions}
    {!!answered.length && <section aria-label="Answered questions" className="rounded-[var(--radius-lg)] bg-card"><Item variant="outline" className="flex-col items-stretch gap-0">
      <div className="flex items-baseline justify-between gap-2 pl-2.5"><h3 className={sectionLabel}>ANSWERED · {answered.length}</h3>
        {answered.length > 3 && <Button variant="link" size="xs" className="underline" data-task-show-answers aria-expanded={showAll} onClick={() => setShowAll(value => !value)}>{showAll ? 'Show latest' : 'Show all'}</Button>}</div>
      <ul className="flex min-w-0 flex-col">{(showAll ? answered : answered.slice(0, 3)).map(question => <AnsweredQuestion key={question.id} question={question} />)}</ul>
    </Item></section>}
    {!!task.files?.length && <section aria-label="Task files" className="rounded-[var(--radius-lg)] bg-card"><Item variant="outline" className="flex-col items-stretch gap-0.5">
      <h3 className={`${sectionLabel} px-2.5 pb-1`}>FILES{folder && ` · ${folder}`}</h3>
      {task.files.map(file => {
        const kind = fileKind(file), [label, Icon] = kind ? kinds[kind] : ['', FileIcon];
        const name = file.name ?? (folder && file.path.startsWith(folder) ? file.path.slice(folder.length) : file.path.split('/').pop());
        const content = <><Icon aria-hidden="true" /><span className="min-w-0 flex-1 truncate text-start text-[13px] font-normal">{name}</span>{label && <span className="text-[11px] font-normal text-muted-foreground">{label}</span>}</>;
        return onOpenFile ? <Button key={file.path} variant="ghost" className="w-full justify-start" data-task-file={file.path} onClick={() => onOpenFile(task, file)}>{content}</Button> : <p key={file.path} className="flex items-center gap-2">{content}</p>;
      })}
    </Item></section>}
    {!!task.history?.length && <section aria-label="Task history" className="rounded-[var(--radius-lg)] bg-card" data-task-history=""><Item variant="outline" className="flex-col items-stretch gap-1">
      <h3 className={sectionLabel}>HISTORY</h3>
      {task.history.map((item, index) => <p key={item.id ?? index} className="text-[13px] break-words text-muted-foreground">{item.note}</p>)}
    </Item></section>}
    {onAsk && <Button variant="link" className="self-start underline" data-task-ask={task.id} onClick={() => onAsk(task)}>{words.ask}</Button>}
  </div>;
}
